      'Baseada em manuscrito em cifra obtido em 1887 pelo reverendo A.F.A. Woodford — provavelmente forjado pelo próprio Westcott.',
      'Sistema de 10 graus correspondendo aos 10 Sephiroth da Árvore da Vida cabalística, divididos em três ordens.',
      'Possuía o maior repositório conhecido de conhecimento mágico ocidental de sua época.',
      'Entrou em colapso após cismas internos, a publicação dos rituais por Aleister Crowley (1909) e por Israel Regardie (1937-1940).',
