    summary: 'Esferas de luz filmadas próximas a crop circles, especialmente em Milk Hill e Wiltshire, Reino Unido. O vídeo mais famoso foi gravado em 1990 em Milk Hill. Interpretadas como OVNIs por uma parte do público, mas identificadas pelo apresentador como "algo muito mais terrível" — entidades espirituais, não tecnologia extraterrestre. Sua presença sistemática nas regiões de crop circles sugere que ambos os fenômenos têm a mesma origem.',
