      'O único organismo com cérebro completamente mapeado é o C. elegans (lombriga), com apenas 302 neurônios — mas mesmo assim os cientistas ainda são incapazes de replicar computacionalmente o comportamento do animal.',
      'O Human Brain Project europeu recebeu €1 bilhão de financiamento (2013–2023); o BRAIN Initiative americano investiu bilhões desde 2013.',
