      'Segundo hadith de Maomé: "O tempo entre a Grande Guerra e a conquista da cidade será de seis anos e o Dajjal surgirá no sétimo."',
      'Batalhará em Al-A\'maq e Dabiq (norte da Síria, fronteira turca) — locais específicos mencionados nos hadith de Abu Hurairah.',
      'O exército muçulmano, composto pelos melhores soldados da época, virá de Medina. Os "romanos" (Rum — hoje interpretados como as potências ocidentais/NATO) pedirão combate direto sem intervenção de terceiros.',
      'A batalha terá quatro rodadas: um terço do exército foge, um terço é martirizado, o terço restante vence na quarta rodada — quando Alá decreta a derrota do inimigo.',
      'Haverá um massacre de proporções extremas: apenas 1 em cada 100 soldados sobreviverá.',
      'No momento da vitória, um grito anunciará que o Dajjal tomou seu lugar entre os descendentes — e os guerreiros jogarão fora as armas e partirão ao seu encontro.',
      'Abu Hurairah (companheiro mais prolífico de hadith de Maomé) e Abdullah ibn Masud (considerado o mais parecido com Maomé em caráter) são as principais fontes dos hadith desta batalha.',
      'Muitos muçulmanos contemporâneos interpretam os conflitos atuais na Síria, Iraque e no cerco geopolítico a Teerã como os "sinais de al-Qiyamah" que precedem a Malhama.',
