    summary: 'Blockbuster de James Cameron (2009) — o filme de maior bilheteria da história até então. Apresenta o transhumanismo como fantasia sedutora: um humano paralítico transfere sua consciência para um corpo Na\'vi alienígena e encontra sentido, força e pertencimento. Promove simultaneamente o pensamento de grupo, o consenso tribal, o misticismo da natureza e a ideia de que a ciência é o portal para um mundo perfeito. Eywa, a deusa-rede de Pandora, é uma versão cinematográfica da noosfera e de Gaia.',
