    cat: 'simbolo',
    icon: '☀',
    source: 30,
    summary: 'O Sonnenrad ("Roda Solar" em alemão), também chamado Sol Negro (Schwarze Sonne), é símbolo de misticismo germânico adotado pelas SS de Himmler como emblema esotérico central. O verdadeiro nome da organização era "Schwarze Sonnen SS" — Tropas do Sol Negro. Em dois níveis simultâneos: simbolicamente, o sol oculto que só os iniciados veem; astronomicamente, nas crenças da Sociedade Vril, o Sol Negro é uma estrela anã marrom no sistema de Aldebaran — o "Segundo Sol" de onde vieram os Arianos. Usado ao lado da suástica e das runas Sieg, é o vértice do sistema simbólico do ocultismo nazista.',
    facts: [
      'O Sonnenrad é uma roda solar de 12 raios, distinta da suástica (4 braços curvos). Representa o sol como força cósmica primordial, presente em culturas indo-europeias desde a pré-história.',
      'O verdadeiro nome das SS era "Schwarze Sonnen SS" (Tropas do Sol Negro) — não apenas "Schutzstaffel" (Tropas de Proteção). O Sol Negro era o culto central, não um ornamento secundário.',
      'Nas crenças da Sociedade Vril: o Sol Negro é uma estrela anã marrom no sistema de Aldebaran (constelação de Touro), chamada de "Segundo Sol". Os Arianos teriam vindo de planetas em torno dessa estrela para a Terra via Mesopotâmia suméria.',
      'Nas SS de Himmler, o Sonnenrad era parte do conjunto simbólico completo: suástica (identidade ariana Völkisch) + runas SS ⚡⚡ (vitória solar) + Sonnenrad (sol oculto/segundo sol) + 12 runas Listianas.',
      'O castelo de Wewelsburg (Westfália) — a "catedral das SS" — tem um mosaico do Sonnenrad no piso da sala circular principal (Obergruppenführersaal). Era o centro ritual da ordem iniciática.',
      'O "Sol Negro" simboliza o sol oculto: o princípio solar que opera nas trevas, na dimensão espiritual inacessível ao comum dos mortais. É a luz que só os iniciados podem ver — gnose reservada aos eleitos.',
      'Persiste em uso no neonazismo e em movimentos esotéricos de extrema direita como a Order of Nine Angles (O9A). Aparece em tatuagens, emblemas e iconografia de grupos que mantêm vivo o ocultismo das SS.',
    ],
    interps: [
      'O Sol Negro inverte a teologia cristã: onde o Deus bíblico é luz que ilumina a todos (Jo 1:4-9), o Sol Negro é uma luz reservada a iniciados — uma iluminação de elite, excludente por definição. É a gnose perfeita: conhecimento que salva e poder que separa.',
      'Que o centro ritual das SS fosse um castelo com um sol negro no piso não é ornamentação: é declaração de intenção. Himmler construiu uma ordem religiosa, com seu templo, seus rituais e seu símbolo sagrado. A diferença entre as SS e uma ordem iniciática como os Cavaleiros Templários era apenas o uniforme.',
      'O ressurgimento do Sonnenrad no neonazismo e no esoterismo contemporâneo demonstra que o projeto espiritual do nazismo não morreu com o Reich. A semente que Guido von List plantou em 1908, que Himmler cultivou nas SS, continua germinando em novos solos — muitas vezes sem que seus portadores conheçam a história completa do símbolo que carregam.',
    ],
