    aliases: ['Demiurgo', 'Demiurge', 'Ialdabaoth', 'deus inferior', 'criador da matéria', 'deus agnóstico'],
    cat: 'historico',
    icon: '⛓️',
    source: 28,
    summary: 'Conceito central da filosofia gnóstica: o Demiurgo (do grego "dēmiourgós", artesão/criador) é uma divindade inferior e imperfeita — ou malévola — que criou o mundo material como uma prisão para aprisioná-las as almas espirituais, separando-as do Deus verdadeiro e transcendente. O mundo físico, na cosmologia gnóstica, não é criação de um Deus bom: é uma jaula. Essa crença é o motor ideológico da busca do CERN: se a matéria é a prisão construída pelo Demiurgo, então destruir partículas de matéria em colisões revelaría o que está "escondido dentro" — o conhecimento que o Demiurgo ocultou.',
    facts: [
      'O termo "Demiurgo" vem de Platão (Timeu), onde é o artesão divino que modela o mundo a partir de formas eternas. Os gnósticos radicalizaram: o Demiurgo não é bom — é inferior, ignorante ou malicioso.',
      'Na cosmologia gnóstica clássica (Valentino, Basílides, séc. II d.C.): o Demiurgo, chamado Ialdabaoth ("filho do caos"), criou o mundo material sem saber que existia um Deus superior. Aprisionou fagulhas de luz divina em corpos físicos.',
      'O objetivo do gnóstico é despertar para sua natureza espiritual superior e escapar da prisão material — o "conhecimento" (gnosis) que liberta.',
      'A crença agnóstica de que "o Demiurgo aprisiona todos na matéria" leva à conclusão lógica: se a matéria for destruída em colisões, o que está escondido dentro da matéria será revelado. É a teologia por trás do LHC.',
      'Sistemas gnósticos — Catarismo (séc. XII, sul da França), Bogomilismo, Mandeísmo, Hermetismo — compartilham a visão da matéria como prisão e buscam a libertação por conhecimento esotérico.',
      'O Catarismo floresceu exatamente na mesma região da França (Languedoc) que hoje abriga as instalações do CERN — e foi exterminado pela Cruzada Albigense (1209-1229) por ordem do Papa.',
      'O agnosticismo materialista moderno é, paradoxalmente, herdeiro da estrutura gnóstica: rejeita o Deus criador pessoal e busca no interior da matéria as respostas que a teologia não dá.',
    ],
    interps: [
      'Se os cientistas do CERN operam — consciente ou inconscientemente — dentro de uma cosmologia gnóstica, então o LHC não é apenas um instrumento científico: é um ritual de libertação gnóstica em escala industrial. Eles tentam "quebrar a prisão" do Demiurgo quebrando a matéria.',
      'A região da França onde está o CERN (Ródano-Alpes, fronteira suíça) é a mesma região onde o Catarismo floresceu e foi destruído. O Catarismo também acreditava que o mundo material era criação de um deus maligno. Coincidência geográfica ou continuidade de tradição?',
      'O Gnosticismo é a ideologia que conecta todas as tradições esotéricas ocidentais: o hermetismo (a matéria oculta a verdade), a maçonaria (o conhecimento proibido que liberta), o transhumanismo (a biologia como prisão a superar). São todos variações do mesmo tema: o homem é mais do que a matéria, e a matéria deve ser transcendida.',
      'O contraste com a Bíblia é total: em Gênesis, a criação material é "muito boa" (Gn 1:31), feita por um Deus pessoal e bom. O Gnosticismo inverte: a matéria é má, o criador é malicioso. Dois sistemas irreconciliáveis — e a escolha entre eles define a cosmovisão de toda a civilização.',
    ],
    refs: ['cern', 'hermetismo', 'grande-obra', 'maconaria', 'transhumanismo', 'teoria-das-cordas'],
