      'O Livro de Daniel e o Apocalipse de João são os textos-chave. A "semana" de 7 anos de Dn 9:27 é identificada com o período da Tribulação. As 7 trombetas, as 7 taças e as marcas da besta (Ap 13) são lidas como eventos literais futuros.',
      'Líderes evangélicos como Jerry Falwell, Pat Robertson, John Hagee e Tim LaHaye popularizaram estas interpretações para dezenas de milhões via TV, livros e filmes (série "Left Behind" vendeu mais de 80 milhões de cópias).',
