      'A estratégia de usar a arqueologia para contradizer a Bíblia é sistêmica: Woolley em Ur (dilúvio local), Evans em Cnossos (civilização "alternativa"), Petrie no Egito (hierarquias raciais). O mesmo projeto, aplicado em diferentes sítios por diferentes agentes do mesmo sistema.',
