    interps: [
      'Não é sobre arqueologia. É sobre a fabricação de uma narrativa da origem da civilização ocidental: uma civilização anterior à grega, de substrato pagão e ocultista, que "antecede" e "fundamenta" a tradição judaico-cristã. Evans não descobriu uma civilização: construiu uma.',
      'O Palácio de Cnossos como atração turística é, na análise do narrador, um "conjunto teatral ao ar livre" onde visitantes são convidados a imaginar o herói semidivino Teseu descendo ao labirinto — um mise-en-scène do mito ocultista, apresentado como história.',
    ],
