    summary: 'Civilização da Idade do Bronze centrada na ilha de Creta (aprox. 3000-1100 a.C.), "descoberta" por Arthur Evans a partir de 1900. Evans a batizou de "minóica" em referência ao lendário rei Minos. É considerada uma das primeiras civilizações avançadas da Europa, precursora da civilização micênica e, indiretamente, da grega clássica. O narrador questiona a neutralidade desta narrativa: Arthur Evans, agente de inteligência britânica, teve controle monopolístico sobre o sítio principal (Cnossos) e reconstruiu o "palácio" com concreto e imaginação artística, fundindo deliberadamente o registro arqueológico com a mitologia grega do Minotauro — transformando um sítio arqueológico em um veículo de legitimação do mito pagão.',
