      'O narrador questiona: Evans não apenas descobriu uma civilização, ele a nomeou em referência a um mito, reconstruiu seu principal sítio como cenário desse mito, e garantiu o controle exclusivo da narrativa. Isso é arqueologia ou é fabricação de uma origem alternativa para a civilização ocidental?',
