    summary: 'Mizraim é filho de Cam (Cão) e neto de Noé, conforme o Quadro das Nações (Gênesis 10). Seu nome em hebraico — Mitsrayim — é a palavra bíblica para "Egito". Fundador e epônimo do povo egípcio segundo a tradição bíblica e semítica. A identificação é reconhecida pela maioria dos estudiosos bíblicos e por parte dos historiadores. O Egito é a nação de Cam, não de Sem — o que, na geopolítica bíblica, tem implicações sobre a natureza da religião e do misticismo que dele emanam.',
