      'A concentração das linhagens malditas — Caim (via Sargão/Uruk) e Canaã (via Ninrode/Babilônia) — no mesmo território é o fundamento das guerras de Israel contra os povos cananeus: não era uma disputa territorial aleatória, mas o confronto entre a linhagem de Set (Israel) e a linhagem de Caim + Canaã.',
